/**
 * COMPILE THE RESEARCH INTO CODE.
 *
 * Reads every docs/research/evidence/<institutionId>.json written by the
 * 7 September 2026 research sweep and writes
 * lib/data/university-evidence.generated.ts. Run it after any evidence file
 * changes; the generated file is committed so the build needs no filesystem.
 *
 *   node qa/build-evidence.mjs
 *
 * It refuses, loudly, anything that would let a wrong claim reach a student:
 *   - an institution id that is not in the catalogue
 *   - a question id that is not in the bank
 *   - a source with no URL, or a URL that is not http(s)
 *   - a tier that is not official / student_report / consultancy
 * Bad question ids are dropped with a warning; bad sources and bad
 * institutions are dropped whole. The summary at the end is the honest count.
 */
import { readdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const dir = join(root, 'docs/research/evidence');
const out = join(root, 'lib/data/university-evidence.generated.ts');

const bank = new Set(
  readFileSync(join(root, 'docs/research/bank-listing.tsv'), 'utf8')
    .split('\n')
    .slice(1)
    .map((l) => l.split('\t')[0])
    .filter(Boolean)
);
const institutions = new Map(
  readFileSync(join(root, 'docs/research/institution-ids.tsv'), 'utf8')
    .split('\n')
    .slice(1)
    .map((l) => l.split('\t'))
    .filter((r) => r[0])
    .map((r) => [r[0], r[1]])
);

const TIERS = new Set(['official', 'student_report', 'consultancy']);
const result = {};
const factsOut = {};
let facts = 0;
let sources = 0;
let mapped = 0;
let unmapped = 0;
const warnings = [];

const files = existsSync(dir) ? readdirSync(dir).filter((f) => f.endsWith('.json')).sort() : [];
for (const f of files) {
  let j;
  try {
    j = JSON.parse(readFileSync(join(dir, f), 'utf8'));
  } catch (e) {
    warnings.push(`${f}: not valid JSON (${e.message})`);
    continue;
  }
  const id = j.institutionId;
  if (!institutions.has(id)) {
    warnings.push(`${f}: unknown institution id "${id}", dropped`);
    continue;
  }
  const clean = [];
  for (const s of j.sources ?? []) {
    if (!s.url || !/^https?:\/\//.test(s.url)) {
      warnings.push(`${id}: source without a valid URL ("${s.title ?? ''}"), dropped`);
      continue;
    }
    if (!TIERS.has(s.tier)) {
      warnings.push(`${id}: source ${s.url} has tier "${s.tier}", dropped`);
      continue;
    }
    const ids = [];
    for (const q of s.questionIds ?? []) {
      if (bank.has(q)) ids.push(q);
      else warnings.push(`${id}: ${s.url} maps unknown question "${q}", dropped`);
    }
    clean.push({
      url: s.url,
      title: String(s.title ?? s.url).slice(0, 200),
      tier: s.tier,
      checkedOn: String(j.checkedOn ?? '2026-09-07'),
      fetched: Boolean(s.fetched),
      fromSnippet: Boolean(s.fromSnippet),
      topics: (s.topics ?? []).map(String).slice(0, 20),
      questionIds: [...new Set(ids)],
      quotes: (s.quotes ?? []).map(String).slice(0, 80),
      unmapped: (s.unmapped ?? []).map(String).slice(0, 80),
      notes: s.notes ? String(s.notes).slice(0, 600) : undefined,
    });
    sources += 1;
    mapped += ids.length;
    unmapped += (s.unmapped ?? []).length;
  }
  const cleanFacts = [];
  for (const f of j.facts ?? []) {
    if (!f?.text || !f?.sourceUrl || !/^https?:\/\//.test(f.sourceUrl)) {
      warnings.push(`${id}: fact without text or a valid URL, dropped`);
      continue;
    }
    cleanFacts.push({
      text: String(f.text).slice(0, 300),
      sourceUrl: f.sourceUrl,
      sourceTitle: String(f.sourceTitle ?? f.sourceUrl).slice(0, 200),
      checkedOn: String(j.checkedOn ?? '2026-09-07'),
    });
  }
  if (cleanFacts.length) {
    factsOut[id] = cleanFacts;
    facts += cleanFacts.length;
  }
  result[id] = {
    institutionId: id,
    checkedOn: String(j.checkedOn ?? '2026-09-07'),
    usesCasShield: typeof j.usesCasShield === 'boolean' ? j.usesCasShield : null,
    sources: clean,
  };
}

const header = `/**
 * GENERATED by qa/build-evidence.mjs from docs/research/evidence/*.json.
 * Do not edit by hand; edit the JSON and re-run the script.
 *
 * ${files.length} institution files, ${sources} sources, ${mapped} question mappings,
 * ${unmapped} verbatim questions not yet in the bank, ${facts} sourced facts. Built ${new Date().toISOString().slice(0, 10)}.
 */
import type { InstitutionEvidence } from '@/lib/data/university-evidence';
import type { InstitutionFact } from '@/lib/data/institution-facts';

export const GENERATED_EVIDENCE: Record<string, InstitutionEvidence> = ${JSON.stringify(result, null, 2)};

/** Sourced facts the sweep captured, merged by profileFor() in institution-facts.ts. */
export const GENERATED_FACTS: Record<string, InstitutionFact[]> = ${JSON.stringify(factsOut, null, 2)};
`;
writeFileSync(out, header);

for (const w of warnings) console.warn('  WARN', w);
console.log(
  `evidence: ${files.length} files, ${Object.keys(result).length} institutions, ${sources} sources, ${mapped} mappings, ${unmapped} unmapped, ${facts} facts, ${warnings.length} warnings`
);
